public async Task<int> AppendProcessingDialogAsync(
    string sourceType,
    string sessionId,
    string requestId,
    IReadOnlyList<ProcessingDialogItemDto> items,
    CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(sourceType);
    ArgumentNullException.ThrowIfNull(sessionId);
    ArgumentNullException.ThrowIfNull(requestId);
    ArgumentNullException.ThrowIfNull(items);
    SyncDbWorkspaceFromContext();

    var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
    if (sessionIdError is not null)
        throw new ArgumentException(sessionIdError, nameof(sessionId));
    var requestIdError = SessionLogIdentifierValidator.ValidateRequestId(requestId);
    if (requestIdError is not null)
        throw new ArgumentException(requestIdError, nameof(requestId));

    // BUG-SESSIONLOG-WS-001..004: child sets carry no workspace query filter,
    // so isolation comes from the explicit parent-session predicate here.
    var currentWorkspaceId = _db.CurrentWorkspaceId;
    var entry = await _db.SessionLogTurns
        .Include(e => e.ProcessingDialog)
        .FirstOrDefaultAsync(e =>
            e.SessionLog!.SourceType == sourceType
            && e.SessionLog.SessionId == sessionId
            && e.SessionLog.WorkspaceId == currentWorkspaceId
            && e.RequestId == requestId, cancellationToken)
        .ConfigureAwait(false)
        ?? throw new InvalidOperationException(
            $"Entry not found: {sourceType}/{sessionId}/{requestId}");

    var nextOrdinal = entry.ProcessingDialog.Count > 0
        ? entry.ProcessingDialog.Max(p => p.Ordinal) + 1
        : 0;

    var workspaceId = ResolveWorkspaceId();
    foreach (var item in items)
    {
        entry.ProcessingDialog.Add(new SessionLogProcessingDialogEntity
        {
            Ordinal = nextOrdinal++,
            Timestamp = ParseDateTimeOffset(item.Timestamp) ?? DateTimeOffset.UtcNow,
            Role = item.Role ?? "model",
            Content = item.Content ?? string.Empty,
            Category = item.Category,
            WorkspaceId = workspaceId
        });
    }

    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    _logger.LogDebug("Appended {Count} dialog items to {SourceType}/{SessionId}/{RequestId}",
        items.Count, sourceType, sessionId, requestId);
    await PublishChangeSafeAsync(
        ChangeEventActions.Updated,
        $"{sourceType}/{sessionId}",
        $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
        cancellationToken).ConfigureAwait(false);

    return entry.ProcessingDialog.Count;
}

public async Task<int> RepairWorkspaceStampsAsync(bool dryRun = false, CancellationToken cancellationToken = default)
{
    SyncDbWorkspaceFromContext();
    var sessions = await _db.SessionLogs
        .IgnoreQueryFilters()
        .Include(s => s.Turns)
            .ThenInclude(t => t.Actions)
        .Include(s => s.Turns)
            .ThenInclude(t => t.Tags)
        .Include(s => s.Turns)
            .ThenInclude(t => t.ContextItems)
        .Include(s => s.Turns)
            .ThenInclude(t => t.ProcessingDialog)
        .Include(s => s.Turns)
            .ThenInclude(t => t.Commits)
                .ThenInclude(c => c.Files)
        .Include(s => s.Turns)
            .ThenInclude(t => t.StringListItems)
        .AsSplitQuery()
        .ToListAsync(cancellationToken)
        .ConfigureAwait(false);

    var changed = 0;
    foreach (var session in sessions)
    {
        var workspaceId = session.WorkspaceId;
        foreach (var turn in session.Turns)
        {
            changed += Restamp(turn.WorkspaceId, workspaceId, value => turn.WorkspaceId = value);
            foreach (var action in turn.Actions)
                changed += Restamp(action.WorkspaceId, workspaceId, value => action.WorkspaceId = value);
            foreach (var tag in turn.Tags)
                changed += Restamp(tag.WorkspaceId, workspaceId, value => tag.WorkspaceId = value);
            foreach (var context in turn.ContextItems)
                changed += Restamp(context.WorkspaceId, workspaceId, value => context.WorkspaceId = value);
            foreach (var dialog in turn.ProcessingDialog)
                changed += Restamp(dialog.WorkspaceId, workspaceId, value => dialog.WorkspaceId = value);
            foreach (var commit in turn.Commits)
                changed += Restamp(commit.WorkspaceId, workspaceId, value => commit.WorkspaceId = value);
            foreach (var stringItem in turn.StringListItems)
                changed += Restamp(stringItem.WorkspaceId, workspaceId, value => stringItem.WorkspaceId = value);
        }
    }

    if (changed > 0 && !dryRun)
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    else if (dryRun)
        _db.ChangeTracker.Clear();

    return changed;

    static int Restamp(string current, string workspaceId, Action<string> setWorkspaceId)
    {
        if (string.Equals(current, workspaceId, StringComparison.Ordinal))
            return 0;

        setWorkspaceId(workspaceId);
        return 1;
    }
}

public async Task<long> UpsertTurnAsync(string sourceType, string sessionId, UnifiedRequestEntryDto turn, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(sourceType);
    ArgumentNullException.ThrowIfNull(sessionId);
    ArgumentNullException.ThrowIfNull(turn);
    SyncDbWorkspaceFromContext();

    var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
    if (sessionIdError is not null)
        throw new ArgumentException(sessionIdError, nameof(sessionId));

    var requestIdError = SessionLogIdentifierValidator.ValidateRequestId(turn.RequestId);
    if (requestIdError is not null)
        throw new ArgumentException(requestIdError, nameof(turn));

    var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
        ?? throw new InvalidOperationException($"Session not found: {sourceType}/{sessionId}");

    var existingTurn = session.Turns.FirstOrDefault(t => t.RequestId == turn.RequestId);
    SessionLogTurnEntity persistedTurn;

    ValidateWorkspaceAttribution(turn, existingTurn);

    if (existingTurn is null)
    {
        ApplyTurnContext(turn, isImport: false, sessionDto: null, session);
        persistedTurn = MapSingleEntry(turn);
        session.Turns.Add(persistedTurn);
    }
    else
    {
        SessionLogTurnContextValidator.ValidateIfSupplied(turn.PlanFile, turn.TodoId);
        if (turn.PlanFile is not null)
            turn.PlanFile = SessionLogTurnContextValidator.ValidatePlanFile(turn.PlanFile, required: true);
        if (turn.TodoId is not null)
            turn.TodoId = SessionLogTurnContextValidator.ValidateTodoId(turn.TodoId, required: true);
        UpdateEntryFromDto(existingTurn, turn, mergeOmittedFields: true);
        persistedTurn = existingTurn;
    }

    ValidateTerminalTurnCompliance(MapTurnEntityToDto(persistedTurn), session.SourceType);

    // BUG-SESSIONLOG-WS-002: the turn and its children inherit the PARENT
    // session's stamp; the ambient workspace never re-stamps the session here.
    StampTurnChildren(persistedTurn, session.WorkspaceId);

    RefreshSessionSummaryFromTurns(session);

    try
    {
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    }
    catch (DbUpdateException ex) when (IsSessionLogTurnUniqueRace(ex))
    {
        // TEST-MCP-SESSIONLIFE-005: two first inserts of the same request id.
        // Retry once as an update of the row that won the race.
        _logger.LogWarning(
            "UNIQUE constraint race for turn {SourceType}/{SessionId}/{RequestId}, retrying as update",
            sourceType,
            sessionId,
            turn.RequestId);
        _db.ChangeTracker.Clear();

        session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
            ?? throw new InvalidOperationException($"Session not found after turn unique race: {sourceType}/{sessionId}");
        var raced = session.Turns.FirstOrDefault(t => t.RequestId == turn.RequestId)
            ?? throw new InvalidOperationException(
                $"Turn {turn.RequestId} disappeared after UNIQUE constraint failure.",
                ex);

        SessionLogTurnContextValidator.ValidateIfSupplied(turn.PlanFile, turn.TodoId);
        if (turn.PlanFile is not null)
            turn.PlanFile = SessionLogTurnContextValidator.ValidatePlanFile(turn.PlanFile, required: true);
        if (turn.TodoId is not null)
            turn.TodoId = SessionLogTurnContextValidator.ValidateTodoId(turn.TodoId, required: true);
        UpdateEntryFromDto(raced, turn, mergeOmittedFields: true);
        ValidateTerminalTurnCompliance(MapTurnEntityToDto(raced), session.SourceType);
        StampTurnChildren(raced, session.WorkspaceId);
        RefreshSessionSummaryFromTurns(session);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        persistedTurn = raced;
    }

    await PublishChangeSafeAsync(
        ChangeEventActions.Updated,
        $"{sourceType}/{sessionId}",
        $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
        cancellationToken).ConfigureAwait(false);

    return persistedTurn.Id;
}

public async Task<long> SetSessionTitleAsync(string sourceType, string sessionId, string title, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(sourceType);
    ArgumentNullException.ThrowIfNull(sessionId);
    ArgumentNullException.ThrowIfNull(title);
    SyncDbWorkspaceFromContext();

    var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
    if (sessionIdError is not null)
        throw new ArgumentException(sessionIdError, nameof(sessionId));

    // TR-MCP-SESSIONLOG-005: dedicated session retitle. Unlike the additive
    // SubmitAsync merge (which the plugin now calls with the title omitted),
    // this explicitly overwrites the session Title so an agent rename sticks.
    var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
        ?? throw new InvalidOperationException($"Session not found: {sourceType}/{sessionId}");

    session.Title = title;
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    await PublishChangeSafeAsync(
        ChangeEventActions.Updated,
        $"{sourceType}/{sessionId}",
        $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
        cancellationToken).ConfigureAwait(false);

    return session.Id;
}

/// <inheritdoc />
public async Task<long> SetTurnTitleAsync(string sourceType, string sessionId, string requestId, string title, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(sourceType);
    ArgumentNullException.ThrowIfNull(sessionId);
    ArgumentNullException.ThrowIfNull(requestId);
    ArgumentNullException.ThrowIfNull(title);
    SyncDbWorkspaceFromContext();

    var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
    if (sessionIdError is not null)
        throw new ArgumentException(sessionIdError, nameof(sessionId));

    var requestIdError = SessionLogIdentifierValidator.ValidateRequestId(requestId);
    if (requestIdError is not null)
        throw new ArgumentException(requestIdError, nameof(requestId));

    // TR-MCP-SESSIONLOG-005: dedicated turn retitle. Explicitly overwrites the
    // turn QueryTitle without the reset-omitted-scalars semantics of
    // ReplaceTurnAsync, so an agent-refined title survives incidental submits.
    var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
        ?? throw new InvalidOperationException($"Session not found: {sourceType}/{sessionId}");

    var turn = session.Turns.FirstOrDefault(t => t.RequestId == requestId)
        ?? throw new InvalidOperationException($"Turn not found: {sourceType}/{sessionId}/{requestId}");

    turn.QueryTitle = title;
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    await PublishChangeSafeAsync(
        ChangeEventActions.Updated,
        $"{sourceType}/{sessionId}",
        $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
        cancellationToken).ConfigureAwait(false);

    return turn.Id;
}

public async Task<bool> DeleteTurnItemAsync(string sourceType, string sessionId, string requestId, string section, string itemKey, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(sourceType);
    ArgumentNullException.ThrowIfNull(sessionId);
    ArgumentNullException.ThrowIfNull(requestId);
    ArgumentNullException.ThrowIfNull(itemKey);
    SyncDbWorkspaceFromContext();

    var parsed = ParseSection(section);
    ValidateTurnIdentifiers(sourceType, sessionId, requestId);

    var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false);
    var turnEntity = session?.Turns.FirstOrDefault(t => t.RequestId == requestId);
    if (session is null || turnEntity is null)
        return false;

    if (!RemoveSectionItem(turnEntity, parsed, itemKey))
        return false;

    StampTurnChildren(turnEntity, session.WorkspaceId);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    await PublishChangeSafeAsync(
        ChangeEventActions.Updated,
        $"{sourceType}/{sessionId}",
        $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
        cancellationToken).ConfigureAwait(false);

    return true;
}

private async Task<TriageReportSubmitResult> SubmitReportCoreAsync(
    TriageReportRequest request,
    CancellationToken cancellationToken)
{
    var validationError = ValidateReport(request);
    if (validationError is not null)
    {
        return new TriageReportSubmitResult
        {
            Success = false,
            Error = validationError,
        };
    }

    var originalWorkspacePath = ResolveSubmittingWorkspace(request);
    var mcpServerRelated = IsQBrainAiRelated(request);
    var effectiveWorkspacePath = await ResolveEffectiveWorkspaceAsync(
        originalWorkspacePath,
        mcpServerRelated,
        cancellationToken).ConfigureAwait(false);
    _db.OverrideWorkspaceId(effectiveWorkspacePath);

    if (!string.IsNullOrWhiteSpace(request.IdempotencyKey))
    {
        var existing = await _db.TriageReports
            .FirstOrDefaultAsync(r => r.IdempotencyKey == request.IdempotencyKey, cancellationToken)
            .ConfigureAwait(false);
        if (existing is not null)
        {
            var existingGroup = await _db.TriageGroups
                .FirstAsync(g => g.GroupId == existing.GroupId, cancellationToken)
                .ConfigureAwait(false);
            return Accepted(existing.ReportId, existing.GroupId, existingGroup.Status, existingGroup.QuietDeadlineUtc, effectiveWorkspacePath);
        }
    }

    var now = _timeProvider.GetUtcNow();
    var fingerprint = BuildFingerprint(request);
    var groupKey = Hash($"{effectiveWorkspacePath}|{fingerprint}");
    var groupId = $"triage-group-{groupKey[..16]}";
    var quietDeadline = now.Add(_options.QuietPeriod);

    var group = await _db.TriageGroups
        .FirstOrDefaultAsync(g => g.GroupKey == groupKey, cancellationToken)
        .ConfigureAwait(false);

    if (group is null)
    {
        group = new TriageGroupEntity
        {
            WorkspaceId = effectiveWorkspacePath,
            GroupId = groupId,
            GroupKey = groupKey,
            EffectiveWorkspacePath = effectiveWorkspacePath,
            Title = request.Title.Trim(),
            Summary = request.Summary.Trim(),
            Status = StatusCollecting,
            ReportCount = 0,
            FirstReportAtUtc = now,
            LastReportAtUtc = now,
            QuietDeadlineUtc = quietDeadline,
            IsQBrainAiRelated = mcpServerRelated,
        };
        _db.TriageGroups.Add(group);
    }

    group.LastReportAtUtc = now;
    group.QuietDeadlineUtc = quietDeadline;
    group.ReportCount += 1;
    if (group.Status == StatusFailed)
    {
        group.Status = StatusCollecting;
        group.LastError = null;
    }

    var reportId = $"triage-report-{Guid.NewGuid():N}";
    var report = new TriageReportEntity
    {
        WorkspaceId = effectiveWorkspacePath,
        ReportId = reportId,
        GroupId = group.GroupId,
        OriginalWorkspacePath = originalWorkspacePath,
        EffectiveWorkspacePath = effectiveWorkspacePath,
        Title = request.Title.Trim(),
        Summary = request.Summary.Trim(),
        ObservedBehavior = TrimOrNull(request.ObservedBehavior),
        ExpectedBehavior = TrimOrNull(request.ExpectedBehavior),
        Severity = TrimOrNull(request.Severity) ?? "medium",
        Component = TrimOrNull(request.Component),
        DedupeKey = TrimOrNull(request.DedupeKey),
        ErrorSignature = TrimOrNull(request.ErrorSignature),
        Fingerprint = fingerprint,
        EvidenceJson = SerializeMap(request.Evidence),
        ListItems = BuildTriageListItems(request, effectiveWorkspacePath),
        ReporterAgent = TrimOrNull(request.ReporterAgent),
        SessionId = TrimOrNull(request.SessionId),
        TurnId = TrimOrNull(request.TurnId),
        CurrentTodoId = TrimOrNull(request.CurrentTodoId),
        IdempotencyKey = TrimOrNull(request.IdempotencyKey),
        Status = ReportStatusGrouped,
        CreatedUtc = now,
    };
    _db.TriageReports.Add(report);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    return Accepted(reportId, group.GroupId, group.Status, group.QuietDeadlineUtc, effectiveWorkspacePath);
}

public async Task<TriageGroupDetail> FlushGroupAsync(string groupId, CancellationToken cancellationToken = default)
{
    var group = await GetGroupEntityAsync(groupId, cancellationToken).ConfigureAwait(false);
    var now = _timeProvider.GetUtcNow();
    if (group.Status == StatusProcessing)
        await FailStaleProcessingRunsAsync(now, group.GroupId, cancellationToken).ConfigureAwait(false);

    group.QuietDeadlineUtc = now;
    if (group.Status == StatusFailed)
    {
        group.Status = StatusCollecting;
        group.LastError = null;
    }

    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    return await ToGroupDetailAsync(group, includeReports: true, cancellationToken).ConfigureAwait(false);
}

/// <inheritdoc />
public async Task<TriageGroupDetail> RetryGroupAsync(
    string groupId,
    bool force = false,
    CancellationToken cancellationToken = default)
{
    var group = await GetGroupEntityAsync(groupId, cancellationToken).ConfigureAwait(false);
    var now = _timeProvider.GetUtcNow();
    if (group.Status == StatusProcessing)
    {
        if (force)
        {
            await ForceFailProcessingRunsAsync(group, now, cancellationToken).ConfigureAwait(false);
        }
        else
        {
            await FailStaleProcessingRunsAsync(now, group.GroupId, cancellationToken).ConfigureAwait(false);
        }

        if (group.Status == StatusProcessing)
            throw new InvalidOperationException($"Triage group '{group.GroupId}' is still processing and cannot be retried yet.");
    }

    await ClearStaleCreatedTodoReferenceForRetryAsync(group, now, cancellationToken).ConfigureAwait(false);

    group.Status = StatusCollecting;
    group.LastError = null;
    group.QuietDeadlineUtc = now;
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    return await ToGroupDetailAsync(group, includeReports: true, cancellationToken).ConfigureAwait(false);
}

/// <inheritdoc />
public async Task<TriageGroupDeleteResult> DeleteGroupAsync(
    string groupId,
    string? reason = null,
    CancellationToken cancellationToken = default)
{
    var group = await GetGroupEntityAsync(groupId, cancellationToken).ConfigureAwait(false);
    var reports = await _db.TriageReports
        .Include(r => r.ListItems)
        .Where(r => r.GroupId == group.GroupId)
        .ToListAsync(cancellationToken)
        .ConfigureAwait(false);

    var now = _timeProvider.GetUtcNow();
    var trimmedReason = string.IsNullOrWhiteSpace(reason) ? null : reason.Trim();
    if (trimmedReason is not null)
    {
        _db.Entry(group).Property("DeleteReason").CurrentValue = trimmedReason;
        foreach (var report in reports)
            _db.Entry(report).Property("DeleteReason").CurrentValue = trimmedReason;
    }

    // Remove is intercepted by McpDbContext into a soft-delete (IsDeleted + DeletedAtUtc).
    // Decomposed report list-items carry a required ReportId, so remove them explicitly to
    // avoid a set-null on those dependent rows.
    foreach (var report in reports)
        _db.RemoveRange(report.ListItems);
    _db.TriageReports.RemoveRange(reports);
    _db.TriageGroups.Remove(group);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    return new TriageGroupDeleteResult
    {
        GroupId = group.GroupId,
        DeletedReportCount = reports.Count,
        DeletedAtUtc = now,
    };
}

public async Task<TriageGroupEditResult> CreateGroupFromSelectionAsync(
    TriageGroupSelectionRequest request,
    CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(request);

    var selection = await ResolveSelectionAsync(request, excludedGroupId: null, cancellationToken).ConfigureAwait(false);
    await EnsureEditableGroupsAsync(selection.SourceGroups, cancellationToken).ConfigureAwait(false);
    var workspacePath = EnsureSingleWorkspace(selection.Reports);
    _db.OverrideWorkspaceId(workspacePath);

    var now = _timeProvider.GetUtcNow();
    var groupKey = Hash($"{workspacePath}|manual|{Guid.NewGuid():N}");
    var group = new TriageGroupEntity
    {
        WorkspaceId = workspacePath,
        GroupId = $"triage-group-{groupKey[..16]}",
        GroupKey = groupKey,
        EffectiveWorkspacePath = workspacePath,
        Title = TrimOrNull(request.Title) ?? selection.Reports.OrderBy(report => report.CreatedUtc).First().Title,
        Summary = TrimOrNull(request.Summary) ?? selection.Reports.OrderBy(report => report.CreatedUtc).First().Summary,
        Status = StatusQueued,
        ReportCount = 0,
        FirstReportAtUtc = now,
        LastReportAtUtc = now,
        QuietDeadlineUtc = now,
        IsQBrainAiRelated = selection.SourceGroups.Any(group => group.IsQBrainAiRelated),
    };
    _db.TriageGroups.Add(group);

    var movedCount = MoveReportsToGroup(selection.Reports, group);
    RefreshGroupAggregate(group, selection.Reports, group.Title, group.Summary, group.QuietDeadlineUtc);
    QueueManualGroup(group, now);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    var removedGroupIds = await RemoveEmptySourceGroupsAsync(
        selection.SourceGroups,
        group.GroupId,
        cancellationToken).ConfigureAwait(false);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    return new TriageGroupEditResult
    {
        Group = await ToGroupDetailAsync(group, includeReports: true, cancellationToken).ConfigureAwait(false),
        RemovedGroupIds = removedGroupIds,
        MovedReportCount = movedCount,
    };
}

/// <inheritdoc />
public async Task<TriageGroupEditResult> ConsolidateIntoGroupAsync(
    string targetGroupId,
    TriageGroupSelectionRequest request,
    CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(request);
    var targetGroup = await GetGroupEntityAsync(targetGroupId, cancellationToken).ConfigureAwait(false);
    var selection = await ResolveSelectionAsync(request, targetGroup.GroupId, cancellationToken).ConfigureAwait(false);
    await EnsureEditableGroupsAsync(selection.SourceGroups.Append(targetGroup).DistinctBy(group => group.GroupId).ToList(), cancellationToken)
        .ConfigureAwait(false);

    var workspacePath = EnsureSingleWorkspace(selection.Reports);
    if (!string.Equals(workspacePath, targetGroup.EffectiveWorkspacePath, StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException("Selected triage reports must belong to the target group workspace.");

    var now = _timeProvider.GetUtcNow();
    var movedCount = MoveReportsToGroup(selection.Reports, targetGroup);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    var targetReports = await _db.TriageReports
        .Where(report => report.GroupId == targetGroup.GroupId)
        .ToListAsync(cancellationToken)
        .ConfigureAwait(false);
    RefreshGroupAggregate(
        targetGroup,
        targetReports,
        targetGroup.Title,
        targetGroup.Summary,
        now.Add(_options.QuietPeriod));
    QueueManualGroup(targetGroup, now);
    var removedGroupIds = await RemoveEmptySourceGroupsAsync(
        selection.SourceGroups,
        targetGroup.GroupId,
        cancellationToken).ConfigureAwait(false);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    return new TriageGroupEditResult
    {
        Group = await ToGroupDetailAsync(targetGroup, includeReports: true, cancellationToken).ConfigureAwait(false),
        RemovedGroupIds = removedGroupIds,
        MovedReportCount = movedCount,
    };
}

private async Task ProcessGroupAsync(TriageGroupEntity group, CancellationToken cancellationToken)
{
    if (!string.IsNullOrWhiteSpace(group.CreatedTodoId))
        return;

    group.Status = StatusProcessing;
    group.LastError = null;
    var run = new TriageResearchRunEntity
    {
        WorkspaceId = group.WorkspaceId,
        RunId = $"triage-run-{Guid.NewGuid():N}",
        GroupId = group.GroupId,
        Status = StatusProcessing,
        PromptTemplateId = _options.PromptTemplateId,
        StartedUtc = _timeProvider.GetUtcNow(),
    };
    _db.TriageResearchRuns.Add(run);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    using var outputLock = new SemaphoreSlim(1, 1);
    async Task AppendAgentOutputAsync(TriageResearchOutputUpdate update)
    {
        if (string.IsNullOrEmpty(update.Text))
            return;

        await outputLock.WaitAsync(CancellationToken.None).ConfigureAwait(false);
        try
        {
            if (string.Equals(update.StreamName, "stderr", StringComparison.OrdinalIgnoreCase))
            {
                run.AgentStderr = AppendRunOutput(run.AgentStderr, update.Text);
            }
            else
            {
                run.AgentStdout = AppendRunOutput(run.AgentStdout, update.Text);
            }

            await _db.SaveChangesAsync(CancellationToken.None).ConfigureAwait(false);
        }
        finally
        {
            outputLock.Release();
        }
    }

    try
    {
        var detail = await ToGroupDetailAsync(group, includeReports: true, cancellationToken).ConfigureAwait(false);
        var groupJson = JsonSerializer.Serialize(detail, typeof(TriageGroupDetail), McpServicesJsonContext.Default);
        var prompt = await RenderPromptAsync(detail, groupJson, cancellationToken).ConfigureAwait(false);
        run.GroupJson = groupJson;
        run.Prompt = prompt;

        var rawResult = await _researchRunner.RunAsync(
            new TriageResearchRequest(detail, groupJson, prompt, group.EffectiveWorkspacePath, AppendAgentOutputAsync),
            cancellationToken).ConfigureAwait(false);
        run.RawOutput = rawResult.OutputJson;
        run.AgentStdout = MergeRunOutput(run.AgentStdout, rawResult.AgentStdout);
        run.AgentStderr = MergeRunOutput(run.AgentStderr, rawResult.AgentStderr);
        run.AgentExitCode = rawResult.AgentExitCode;

        if (!rawResult.Success)
        {
            MarkResearchFailure(group, run, rawResult.Error ?? "Triage research runner failed.");
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            return;
        }

        var schema = ValidateResearchOutput(rawResult.OutputJson);
        var researchOutput = schema.Output;
        var schemaError = schema.Error;
        if ((!schema.Valid || researchOutput is null) && !ContainsJsonObject(rawResult.OutputJson))
        {
            researchOutput = BuildFallbackResearchOutput(
                detail,
                schemaError ?? "Triage research output failed schema validation.",
                run.RunId);
        }

        if (researchOutput is null)
        {
            MarkResearchFailure(group, run, schemaError ?? "Triage research output failed schema validation.");
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            return;
        }

        TriageTodoCreationAttempt creationAttempt;
        await TodoCreationLock.WaitAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            creationAttempt = await CreateTriageTodoWithRetryAsync(group, researchOutput, cancellationToken)
                .ConfigureAwait(false);
        }
        finally
        {
            TodoCreationLock.Release();
        }

        var todoId = creationAttempt.RequestedTodoId;
        var createResult = creationAttempt.Result;
        var todoCreatedWithWarning = creationAttempt.CreatedWithWarning;
        if (createResult is null)
            throw new InvalidOperationException("Triage TODO creation did not return a result.");

        if (!createResult.Success && !todoCreatedWithWarning)
        {
            MarkResearchFailure(group, run, createResult.Error ?? "TODO creation failed.");
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            return;
        }

        var createdTodoId = createResult.Item?.Id ?? todoId;
        group.CreatedTodoId = createdTodoId;
        group.Status = StatusCompleted;
        group.LastError = todoCreatedWithWarning ? createResult.Error : null;
        run.CreatedTodoId = createdTodoId;
        run.Status = StatusCompleted;
        run.Error = todoCreatedWithWarning ? createResult.Error : null;
        run.ResponseJson = JsonSerializer.Serialize(researchOutput, typeof(ResearchOutput), McpServicesJsonContext.Default);
        run.CompletedUtc = _timeProvider.GetUtcNow();
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    }
    catch (Exception ex) when (ex is not OperationCanceledException)
    {
        _logger.LogWarning(ex, "Triage research failed for group {GroupId}.", group.GroupId);
        MarkResearchFailure(group, run, ex.Message);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    }
}

private async Task<int> FailStaleProcessingRunsAsync(
    DateTimeOffset now,
    string? groupId,
    CancellationToken cancellationToken)
{
    var maxRunTime = GetEffectiveMaxRunTime();
    var staleStartedBeforeUtc = now - maxRunTime;
    var query = _db.TriageResearchRuns
        .IgnoreQueryFilters()
        .Where(run => run.Status == StatusProcessing && run.StartedUtc <= staleStartedBeforeUtc);
    if (!string.IsNullOrWhiteSpace(groupId))
    {
        var trimmedGroupId = groupId.Trim();
        query = query.Where(run => run.GroupId == trimmedGroupId);
    }

    var staleRuns = await query
        .ToListAsync(cancellationToken)
        .ConfigureAwait(false);
    if (staleRuns.Count == 0)
        return 0;

    var staleGroupIds = staleRuns
        .Select(run => run.GroupId)
        .Distinct(StringComparer.Ordinal)
        .ToArray();
    var staleGroups = await _db.TriageGroups
        .IgnoreQueryFilters()
        .Where(group => staleGroupIds.Contains(group.GroupId))
        .ToListAsync(cancellationToken)
        .ConfigureAwait(false);
    var error = $"Triage research run exceeded the configured maximum duration ({maxRunTime}) and was marked failed for retry.";

    foreach (var run in staleRuns)
    {
        run.Status = StatusFailed;
        run.Error = error;
        run.CompletedUtc = now;

        var group = staleGroups.FirstOrDefault(candidate =>
            string.Equals(candidate.GroupId, run.GroupId, StringComparison.Ordinal) &&
            string.Equals(candidate.WorkspaceId, run.WorkspaceId, StringComparison.Ordinal));
        if (group is null ||
            !string.Equals(group.Status, StatusProcessing, StringComparison.OrdinalIgnoreCase) ||
            !string.IsNullOrWhiteSpace(group.CreatedTodoId))
        {
            continue;
        }

        group.Status = StatusFailed;
        group.LastError = error;
    }

    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    return staleRuns.Count;
}

private async Task<HandoffIngestionResult> PersistAsync(
    HandoffIngestionRequest request,
    string workspacePath,
    HandoffResolvedSource resolved,
    HandoffTodoDraft? draft,
    List<HandoffDiagnostic> diagnostics,
    bool created,
    bool replayed,
    bool requiresReview,
    HandoffReviewState reviewState,
    string? createdTodoId,
    string? agent,
    string? model,
    bool success,
    string? error,
    CancellationToken cancellationToken,
    string? errorCode = null)
{
    var runId = $"handoff-run-{Guid.NewGuid():N}";
    var sanitizedDraft = SanitizeDraft(draft);
    var entity = new HandoffIngestionRunEntity
    {
        RunId = runId,
        WorkspaceId = workspacePath,
        SourceKind = resolved.SourceKind.ToString(),
        SourceLocator = SanitizeText(resolved.Locator) ?? resolved.Locator,
        ContentSha256 = resolved.ContentSha256 ?? string.Empty,
        ExtractedAtUtc = _time.GetUtcNow(),
        PromptVersion = HandoffPromptDefaults.PromptVersion,
        TemplateVersion = HandoffPromptDefaults.TemplateId,
        Agent = SanitizeText(agent),
        Model = SanitizeText(model),
        Confidence = sanitizedDraft?.Confidence,
        Mode = request.Mode.ToString(),
        ReviewState = reviewState.ToString(),
        CreatedTodoId = createdTodoId,
        DraftJson = sanitizedDraft is null ? null : JsonSerializer.Serialize(sanitizedDraft, DraftJsonOptions),
        Force = request.Force,
        ReplayIdentity = HandoffReplayKeys.Create(
            workspacePath,
            resolved.ContentSha256 ?? string.Empty,
            HandoffPromptDefaults.PromptVersion,
            request.Force || string.IsNullOrEmpty(resolved.ContentSha256),
            runId),
        ProcessingState = nameof(HandoffProcessingState.Terminal),
        Succeeded = success,
        Error = SanitizeText(error),
        ErrorCode = errorCode,
    };
    ReplaceDiagnostics(entity, diagnostics);
    _db.HandoffIngestionRuns.Add(entity);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    var result = MapEntity(entity, replayed);
    result.Success = success;
    result.Created = created;
    result.RequiresReview = requiresReview;
    result.Error = error;
    result.ErrorCode = errorCode;
    return result;
}

private async Task<(HandoffIngestionRunEntity? Entity, bool Replayed, bool InProgress)> TryReserveRunAsync(
    HandoffIngestionRequest request,
    string workspacePath,
    HandoffResolvedSource resolved,
    CancellationToken cancellationToken)
{
    var runId = $"handoff-run-{Guid.NewGuid():N}";
    var identity = HandoffReplayKeys.Create(
        workspacePath,
        resolved.ContentSha256 ?? string.Empty,
        HandoffPromptDefaults.PromptVersion,
        request.Force,
        runId);
    if (!request.Force)
    {
        var existing = await _db.HandoffIngestionRuns
            .Include(run => run.Diagnostics)
            .FirstOrDefaultAsync(run => run.ReplayIdentity == identity, cancellationToken)
            .ConfigureAwait(false);
        if (existing is not null)
            return await ResolveExistingReservationAsync(existing, cancellationToken).ConfigureAwait(false);
    }

    var now = _time.GetUtcNow();
    var entity = new HandoffIngestionRunEntity
    {
        RunId = runId,
        WorkspaceId = workspacePath,
        SourceKind = resolved.SourceKind.ToString(),
        SourceLocator = SanitizeText(resolved.Locator) ?? resolved.Locator,
        ContentSha256 = resolved.ContentSha256 ?? string.Empty,
        ExtractedAtUtc = now,
        PromptVersion = HandoffPromptDefaults.PromptVersion,
        TemplateVersion = HandoffPromptDefaults.TemplateId,
        Mode = request.Mode.ToString(),
        ReviewState = nameof(HandoffReviewState.None),
        Force = request.Force,
        ReplayIdentity = identity,
        Succeeded = false,
        ProcessingState = nameof(HandoffProcessingState.Processing),
        ProcessingOwner = _instanceId,
        ProcessingLeaseExpiresAtUtc = now.Add(_lease.Duration),
    };
    _db.HandoffIngestionRuns.Add(entity);
    try
    {
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return (entity, false, false);
    }
    catch (DbUpdateException ex) when (HandoffDbExceptions.IsUniqueViolation(ex))
    {
        _db.Entry(entity).State = EntityState.Detached;
        var winner = await _db.HandoffIngestionRuns
            .Include(run => run.Diagnostics)
            .FirstAsync(run => run.ReplayIdentity == identity, cancellationToken)
            .ConfigureAwait(false);
        return await ResolveExistingReservationAsync(winner, cancellationToken).ConfigureAwait(false);
    }
}

private async Task<bool> SaveRunAfterTodoAsync(HandoffIngestionRunEntity entity, CancellationToken cancellationToken)
{
    try
    {
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return true;
    }
    catch (OperationCanceledException) when (!string.IsNullOrWhiteSpace(entity.CreatedTodoId))
    {
        if (!await TryCompensateCreatedRunAsync(entity).ConfigureAwait(false))
            throw;
        throw;
    }
    catch (Exception ex) when (!string.IsNullOrWhiteSpace(entity.CreatedTodoId) && HandoffDbExceptions.IsCommitAmbiguous(ex))
    {
        if (!await TryCompensateCreatedRunAsync(entity).ConfigureAwait(false))
            throw;
        return true;
    }
}

public async Task<HostileReviewResult> SubmitAsync(HostileReviewSubmitRequest request, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(request);
    cancellationToken.ThrowIfCancellationRequested();

    if (!string.IsNullOrWhiteSpace(request.WorkspacePath)
        && !IsSameWorkspace(request.WorkspacePath, _workspaceId, QBrainAi.Client.WorkspacePathNormalizer.Process)
        && !string.Equals(request.WorkspacePath, _workspaceId, StringComparison.OrdinalIgnoreCase))
    {
        return new HostileReviewResult
        {
            Success = false,
            HttpStatus = 403,
            ErrorCode = "foreign_workspace",
            Error = "The request workspace does not match the authenticated workspace.",
        };
    }

    var payload = request.SerializedPayload ?? JsonSerializer.Serialize(request);
    var payloadBytes = Encoding.UTF8.GetByteCount(payload);
    if (payloadBytes > _options.MaximumSubmitBytes)
    {
        return new HostileReviewResult
        {
            Success = false,
            HttpStatus = 400,
            ErrorCode = "payload_too_large",
            Error = "Serialized request exceeds 1,048,576 bytes.",
        };
    }

    if (request.Links.Count > _options.MaximumLinks)
    {
        return new HostileReviewResult
        {
            Success = false,
            HttpStatus = 400,
            ErrorCode = "too_many_links",
            Error = "More than 64 artifact links is rejected.",
        };
    }

    var active = await _db.HostileReviewRequests
        .CountAsync(item => item.Status == "Queued" || item.Status == "Claimed" || item.Status == "Running", cancellationToken)
        .ConfigureAwait(false);
    if (active >= _options.MaximumActiveQueue)
    {
        return new HostileReviewResult
        {
            Success = false,
            HttpStatus = 429,
            ErrorCode = "queue_full",
            Error = "Hostile review queue is at capacity.",
        };
    }

    var now = _time.GetUtcNow();
    var requestId = $"hr-{now:yyyyMMddHHmmss}-{Guid.NewGuid():N}";
    var entity = new HostileReviewRequestEntity
    {
        RequestId = requestId,
        WorkspaceId = _workspaceId,
        TargetType = string.IsNullOrWhiteSpace(request.TargetType) ? "code" : request.TargetType.Trim(),
        Mode = string.IsNullOrWhiteSpace(request.Mode) ? "adversarial" : request.Mode.Trim(),
        ScopeStatement = request.ScopeStatement ?? string.Empty,
        RequestingAgent = string.IsNullOrWhiteSpace(request.RequestingAgent) ? "unknown" : request.RequestingAgent.Trim(),
        Status = "Queued",
        CreatedUtc = now,
        UpdatedUtc = now,
    };

    foreach (var link in request.Links)
    {
        var resolution = ResolveLink(link);
        entity.Links.Add(new HostileReviewArtifactLinkEntity
        {
            RequestId = requestId,
            WorkspaceId = _workspaceId,
            ArtifactType = string.IsNullOrWhiteSpace(link.ArtifactType) ? "unknown" : link.ArtifactType.Trim(),
            ArtifactId = link.ArtifactId ?? string.Empty,
            ContentSha256 = resolution.Hash,
            Resolved = resolution.Resolved,
        });
        if (!string.IsNullOrWhiteSpace(resolution.DiagnosticCode))
        {
            entity.Diagnostics.Add(new HostileReviewDiagnosticEntity
            {
                RequestId = requestId,
                WorkspaceId = _workspaceId,
                Code = resolution.DiagnosticCode,
                Message = resolution.DiagnosticMessage ?? resolution.DiagnosticCode,
            });
        }
    }

    _db.HostileReviewRequests.Add(entity);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    return Map(entity);
}

public async Task<HostileReviewResult> AcceptReviewerOutputAsync(string requestId, HostileReviewerOutput output, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(output);
    var entity = await LoadAsync(requestId, cancellationToken).ConfigureAwait(false);
    if (entity is null)
        return NotFound(requestId);

    if (!string.Equals(output.Model, HostileReviewPromptDefaults.RequiredModel, StringComparison.Ordinal)
        || !string.Equals(output.Effort, HostileReviewPromptDefaults.RequiredEffort, StringComparison.Ordinal))
    {
        entity.Status = "Failed";
        entity.LastErrorCode = "ModelUnavailable";
        entity.UpdatedUtc = _time.GetUtcNow();
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        var failed = Map(entity);
        failed.ErrorCode = "ModelUnavailable";
        failed.Success = false;
        return failed;
    }

    if (!AllowedVerdicts.Contains(output.Verdict))
    {
        entity.Status = "Failed";
        entity.LastErrorCode = "malformed_output";
        entity.UpdatedUtc = _time.GetUtcNow();
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        var failed = Map(entity);
        failed.ErrorCode = "malformed_output";
        failed.Success = false;
        return failed;
    }

    var now = _time.GetUtcNow();
    entity.Executions.Add(new HostileReviewExecutionEntity
    {
        ExecutionId = $"hrex-{Guid.NewGuid():N}",
        RequestId = entity.RequestId,
        WorkspaceId = entity.WorkspaceId,
        ReviewerAgent = output.ReviewerAgent,
        Model = output.Model,
        Effort = output.Effort,
        SourceSurface = output.SourceSurface,
        PromptTemplateId = output.PromptTemplateId,
        PromptVersion = output.PromptVersion,
        StartedUtc = now,
        EndedUtc = now,
        InputTokens = output.InputTokens,
        OutputTokens = output.OutputTokens,
    });

    foreach (var finding in output.Findings)
    {
        var category = AllowedCategories.Contains(finding.Category) ? finding.Category : "uncertainty";
        entity.Findings.Add(new HostileReviewFindingEntity
        {
            RequestId = entity.RequestId,
            WorkspaceId = entity.WorkspaceId,
            Category = category,
            Severity = string.IsNullOrWhiteSpace(finding.Severity) ? "medium" : finding.Severity,
            ArtifactId = finding.ArtifactId,
            Location = finding.Location,
            RequirementId = finding.RequirementId,
            EvidenceSummary = finding.EvidenceSummary,
            Recommendation = finding.Recommendation,
        });
    }

    entity.Verdict = output.Verdict.ToUpperInvariant();
    entity.QualityDisclosure = output.RequestQuality.Disclosure;
    entity.QualityScopeClarity = output.RequestQuality.ScopeClarity;
    entity.QualityObjectiveClarity = output.RequestQuality.ObjectiveClarity;
    entity.QualityConfidence = output.RequestQuality.Confidence;
    entity.QualityEnoughContext = output.RequestQuality.EnoughContext;
    entity.Status = "Succeeded";
    entity.UpdatedUtc = now;
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    return Map(entity);
}

public async Task<TodoMutationResult> RestoreAsync(TodoCompensationSnapshot snapshot, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(snapshot);
    if (snapshot.State is not EfTodoCompensationState state)
    {
        return new TodoMutationResult(
            false,
            $"TODO compensation snapshot provider '{snapshot.Provider}' is not supported by {nameof(EfTodoService)}.",
            FailureKind: TodoMutationFailureKind.Conflict);
    }

    await _writeLock.WaitAsync(cancellationToken).ConfigureAwait(false);
    try
    {
        await using var scope = CreateScope();
        var ctx = scope.Context;
        var workspaceId = string.IsNullOrWhiteSpace(state.Item.WorkspaceId)
            ? ctx.CurrentWorkspaceId
            : state.Item.WorkspaceId;
        var existing = await ctx.TodoItems
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(row => row.WorkspaceId == workspaceId && row.Id == state.Item.Id, cancellationToken)
            .ConfigureAwait(false);
        TodoItemEntity restored;
        if (existing is null)
        {
            restored = CloneTodoItem(state.Item);
            ctx.TodoItems.Add(restored);
        }
        else
        {
            CopyTodoItem(state.Item, existing);
            restored = existing;
        }

        // Restore the 4NF child rows dependent-side: replace whatever rows exist (including
        // soft-deleted ones) with the captured snapshot's children.
        var staleListRows = await ctx.TodoItemListItems
            .IgnoreQueryFilters()
            .Where(r => r.WorkspaceId == workspaceId && r.TodoId == state.Item.Id)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);
        var staleTaskRows = await ctx.TodoItemTasks
            .IgnoreQueryFilters()
            .Where(r => r.WorkspaceId == workspaceId && r.TodoId == state.Item.Id)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);
        ctx.TodoItemListItems.RemoveRange(staleListRows);
        ctx.TodoItemTasks.RemoveRange(staleTaskRows);
        ctx.TodoItemListItems.AddRange(restored.ListItems);
        ctx.TodoItemTasks.AddRange(restored.ImplementationTaskRows);

        ApplySoftDeleteState(ctx.Entry(restored), state.SoftDelete);
        await RestoreDocumentMetadataAsync(ctx, state.DocumentMetadata, cancellationToken).ConfigureAwait(false);

        var restoredFlat = ToFlatItem(restored);
        await SyncTodoRequirementLinksAsync(ctx, restored, restoredFlat, cancellationToken).ConfigureAwait(false);
        await AppendAuditAsync(ctx, restored.Id, "restored", restoredFlat, null, "transaction_rollback", cancellationToken).ConfigureAwait(false);
        await ctx.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        return await FinalizeMutationAsync(ChangeEventActions.Updated, restored.Id, restoredFlat, cancellationToken).ConfigureAwait(false);
    }
    finally
    {
        _writeLock.Release();
    }
}

